Here is the root cause:
filemap_fault() may drop mmap_lock before returning VM_FAULT_RETRY, allowing a concurrent munmap to free the vm_area_struct via RCU. The subsequent trace_ocfs2_fault() call dereferences the now-dangling vma pointer, causing a use-after-free.

Here is the patch:

 static vm_fault_t ocfs2_fault(struct vm_fault *vmf)
 {
-	struct vm_area_struct *vma = vmf->vma;
+	unsigned long long ip_blkno =
+		OCFS2_I(file_inode(vmf->vma->vm_file))->ip_blkno;
 	sigset_t oldset;
 	vm_fault_t ret;

 	ocfs2_block_signals(&oldset);
 	ret = filemap_fault(vmf);
 	ocfs2_unblock_signals(&oldset);

-	trace_ocfs2_fault(OCFS2_I(vma->vm_file->f_mapping->host)->ip_blkno,
-			  vma, vmf->page, vmf->pgoff);
+	trace_ocfs2_fault(ip_blkno, vmf->page, vmf->pgoff);
 	return ret;
 }
-
 static vm_fault_t __ocfs2_page_mkwrite(struct file *file,
 			struct buffer_head *di_bh, struct folio *folio)
 {
 	int err;
 	vm_fault_t ret = VM_FAULT_NOPAGE;
 	struct inode *inode = file_inode(file);
 	struct address_space *mapping = inode->i_mapping;
 	loff_t pos = folio_pos(folio);
 	unsigned int len = PAGE_SIZE;
 	pgoff_t last_index;
 	struct folio *locked_folio = NULL;
 	void *fsdata;
 	loff_t size = i_size_read(inode);

 	last_index = (size - 1) >> PAGE_SHIFT;

 	/*
 	 * There are cases that lead to the page no longer belonging to the
 	 * mapping.
 	 * 1) pagecache truncates locally due to memory pressure.
 	 * 2) pagecache truncates when another is taking EX lock against 
 	 * inode lock. see ocfs2_data_convert_worker.
 	 * 
 	 * The i_size check doesn't catch the case where nodes truncated and
 	 * then re-extended the file. We'll re-check the page mapping after
 	 * taking the page lock inside of ocfs2_write_begin_nolock().
 	 *
 	 * Let VM retry with these cases.
 	 */
 	if ((folio->mapping != inode->i_mapping) ||
 	    !folio_test_uptodate(folio) ||
 	    (pos >= size))
 		goto out;

 	/*
 	 * Call ocfs2_write_begin() and ocfs2_write_end() to take
 	 * advantage of the allocation code there. We pass a write
 	 * length of the whole page (chopped to i_size) to make sure
 	 * the whole thing is allocated.
 	 *
 	 * Since we know the page is up to date, we don't have to
 	 * worry about ocfs2_write_begin() skipping some buffer reads
 	 * because the "write" would invalidate their data.
 	 */
 	if (folio->index == last_index)
 		len = ((size - 1) & ~PAGE_MASK) + 1;

 	err = ocfs2_write_begin_nolock(mapping, pos, len, OCFS2_WRITE_MMAP,
 				       &locked_folio, &fsdata, di_bh, folio);
 	if (err) {
 		if (err != -ENOSPC)
 			mlog_errno(err);
 		ret = vmf_error(err);
 		goto out;
 	}

 	if (!locked_folio) {
 		ret = VM_FAULT_NOPAGE;
 		goto out;
 	}
 	err = ocfs2_write_end_nolock(mapping, pos, len, len, fsdata);
 	BUG_ON(err != len);
 	ret = VM_FAULT_LOCKED;
 out:
 	return ret;
 }



